ALTER TABLE audit_logs ALTER COLUMN actor_id DROP NOT NULL;ALTER TABLE audit_logs ADD COLUMN actor_kind text NOT NULL DEFAULT 'user' CHECK(actor_kind IN('user','worker'));ALTER TABLE audit_logs ADD CONSTRAINT audit_actor_identity CHECK((actor_kind='user' AND actor_id IS NOT NULL)OR(actor_kind='worker' AND actor_id IS NULL));
CREATE OR REPLACE FUNCTION expire_one_staff_booking() RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public AS $$DECLARE candidate record;b public.bookings%ROWTYPE;BEGIN FOR candidate IN SELECT id,organization_id,property_id,room_id FROM public.bookings WHERE origin='staff' AND state='held' AND hold_deadline<=clock_timestamp() ORDER BY hold_deadline LIMIT 50 LOOP IF NOT pg_try_advisory_xact_lock(hashtextextended('inventory-location:'||candidate.organization_id::text||':'||candidate.property_id::text,0)) THEN CONTINUE;END IF;PERFORM 1 FROM public.rooms WHERE id=candidate.room_id FOR UPDATE;SELECT * INTO b FROM public.bookings WHERE id=candidate.id FOR UPDATE;IF b.state<>'held' OR b.hold_deadline>clock_timestamp() THEN CONTINUE;END IF;UPDATE public.bookings SET state='expired',version=version+1,decision_reason='Hold deadline elapsed' WHERE id=b.id;UPDATE public.room_allocations SET state='released',version=version+1,released_at=clock_timestamp() WHERE booking_id=b.id AND state='active';UPDATE public.invoices SET state='void',voided_at=clock_timestamp(),void_reason='Booking hold expired before verified payment' WHERE booking_id=b.id AND state='issued';INSERT INTO public.booking_events_outbox(organization_id,property_id,booking_id,event)VALUES(b.organization_id,b.property_id,b.id,'expired')ON CONFLICT DO NOTHING;INSERT INTO public.audit_logs(organization_id,actor_kind,action,object_id,details)VALUES(b.organization_id,'worker','booking.expired',b.id,jsonb_build_object('source','worker','version',b.version+1));RETURN true;END LOOP;RETURN false;END $$;REVOKE ALL ON FUNCTION expire_one_staff_booking() FROM PUBLIC;GRANT EXECUTE ON FUNCTION expire_one_staff_booking() TO kost_worker;
